INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4057fce5-7e08-416c-915e-06c341a033da', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h1>Condiciones para los pagos mediante nota de débito en el procedimiento de notas de débito básicas SEPA</h1>', '993cb3f9-d781-47ed-948c-3d87e74c3aa4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('db97ed4f-59e1-4a2f-93ba-76c1a0963a1a', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p><br></p>', '818b1bf9-02c4-4be0-bb9a-f9a389ecf1ec');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0cfaa7b9-9362-49de-8b20-ff373c044b0f', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p><strong>The present translation is furnished for the customer&#39;s convenience only. The original German text of the Terms and Conditions for Payments by Direct Debit under the SEPA Core Direct Debit Scheme (Bedingungen für Zahlungen mittels Lastschrift im SEPA-Basislastschriftverfahren) is binding in all respects. In the event of any divergence between the English and the German texts, constructions, meanings or interpretations, the German text, constructions, meanings or interpretations shall govern exclusively.</strong></p>', '818b1bf9-02c4-4be0-bb9a-f9a389ecf1ec');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7b8b7f6f-b000-47ae-8f3c-3db52eae4e3a', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p><strong>La presente traducción se provee solamente por conveniencia para el cliente. El texto original en Alemán de los Condiciones para las operaciones de transferencias (Bedingungen für den Überweisungsverkehr) es vinculante en todos los respectos. En caso de que hubiera cualquier divergencia entre los textos, construcciones, significados o interpretaciones españolas y alemanas; el texto alemán y sus construcciones, significados e interpretaciones regirán de manera exclusiva.</strong></p>', '818b1bf9-02c4-4be0-bb9a-f9a389ecf1ec');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8f151d45-73bb-403e-b375-27526fc3d434', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Für Zahlungen des Kunden an Zahlungsempfänger mittels SEPA-Basislastschrift über sein Konto bei der Bank gelten folgende Bedingungen:</p>', 'e5259d7f-e04e-4d03-b34f-4c5f6f1dfac0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2ce1d7c6-9128-420a-8b1b-8979c076e833', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>Payments which the customer makes to payees (creditors) by SEPA core direct debit Scheme through his/her account with the Bank shall be subject to the following terms and conditions:</p>', 'e5259d7f-e04e-4d03-b34f-4c5f6f1dfac0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a455acfb-febb-4b60-be4d-2d8826e5c59a', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Para los pagos del cliente a beneficiarios de pagos mediante notas de débito básicas SEPA a través de su cuenta en el Banco rigen las siguientes condiciones:</p>', 'e5259d7f-e04e-4d03-b34f-4c5f6f1dfac0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bc2b8ee8-3bd4-404b-8d9d-a31d4ee94597', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>1. Allgemein</h2>', '2764df30-ef60-4bac-854f-f9e42ca56e05');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f867bb20-9162-4e7b-8979-7c933bf7703c', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>1. General</h2>', '2764df30-ef60-4bac-854f-f9e42ca56e05');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4af624de-f293-437f-b65e-78ad971b2f56', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>1. Generalidades</h2>', '2764df30-ef60-4bac-854f-f9e42ca56e05');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e4936a68-37f6-4c3d-b6e5-65c6f0880f68', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>1.1 Begriffsbestimmung</h2>', 'e4f83d7a-3398-4bc9-9d3c-d7c60a6db4e2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bf2c7047-5fd1-455d-9ed4-b1a1d094438d', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>1.1 Definition</h2>', 'e4f83d7a-3398-4bc9-9d3c-d7c60a6db4e2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('951bbe3c-0e72-4b8e-a218-7ddb888c3eac', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>1.1 Definición de conceptos</h2>', 'e4f83d7a-3398-4bc9-9d3c-d7c60a6db4e2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b5309809-6c1f-4908-a3b2-ea77cb871f2d', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Eine Lastschrift ist ein vom Zahlungsempfänger ausgelöster Zahlungsvorgang zu Lasten des Kontos des Kunden, bei dem die Höhe des jeweiligen Zahlungsbetrages vom Zahlungsempfänger angegeben wird.</p>', '27a92298-b4cc-4ed2-9b8e-726ab887a97d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c6737116-461b-4557-a1e5-27040d8ff977', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>A direct debit is a payment transaction initiated by the payee and debited to the customer&#39;s account where the amount of the payment is specified by the payee.</p>', '27a92298-b4cc-4ed2-9b8e-726ab887a97d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('87f544bc-b1c7-432c-8fce-c85257ab551d', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>La nota de débito es una operación de pago iniciada por el beneficiario del pago con cargo a la cuenta del cliente, en la cual el beneficiario del pago indica el total del importe del pago.</p>', '27a92298-b4cc-4ed2-9b8e-726ab887a97d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a48f165d-8478-4994-9bfa-9dca7bdc22f3', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>1.2 Entgelte und deren Änderung</h2>', 'b356357c-b2d9-4b13-94fd-d1e2f2aea506');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('84f8992f-62c7-4e99-8f1f-ea3007057908', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>1.2 Charges and their change</h2>', 'b356357c-b2d9-4b13-94fd-d1e2f2aea506');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4fab6c0f-f73e-4912-a049-c2466c8813d1', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>1.2 Comisiones y su modificación</h2>', 'b356357c-b2d9-4b13-94fd-d1e2f2aea506');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c6fa87b0-4332-4d7d-9d2c-537f62cc0840', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>1.2.1 Entgelte für Verbraucher</h2>', 'de0ba084-a162-4123-b799-ce502e6abcd5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('38753f72-4cdf-47b8-9035-ebe95bc33b66', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>1.2.1 Charges for consumers</h2>', 'de0ba084-a162-4123-b799-ce502e6abcd5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('21050af0-cdd4-4a92-aa3a-ea4ee603840b', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>1.2.1 Comisiones en caso de tratarse de consumidores</h2>', 'de0ba084-a162-4123-b799-ce502e6abcd5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1d578de3-7a3a-4aea-a947-91cd5db410bf', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Die Entgelte im Lastschriftverkehr ergeben sich aus dem «Preis- und Leistungsverzeichnis». Änderungen der Entgelte im Lastschriftverkehr werden dem Kunden spätestens zwei Monate vor dem Zeitpunkt ihres Wirksamwerdens in Textform angeboten. Hat der Kunde mit der Bank im Rahmen der Geschäftsbeziehung einen elektronischen Kommunikationsweg vereinbart, können die Änderungen auch auf diesem Wege angeboten werden. Die von der Bank angebotenen Änderungen werden nur wirksam, wenn der Kunde diese annimmt. Eine Vereinbarung über die Änderung eines Entgelts, das auf eine über die Hauptleistung hinausgehende Zahlung des Kunden gerichtet ist, kann die Bank mit dem Kunden nur ausdrücklich treffen.</p>', '302f70b2-d5cc-4ffa-aa18-283abd63bc7c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ff4677fc-8acd-4131-9c26-ea0c716bc02b', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The charges for direct debits shall be set out in the &quot;Schedule of prices and services&quot; (&quot;Preis- und Leistungsverzeichnis&quot;). Any changes in the charges in direct debit transactions shall be offered to the customer in text form no later than two months before their proposed date of entry into force. If the customer has agreed an electronic communication channel with the Bank within the framework of the business relationship, the changes may also be offered through this channel. The changes offered by the Bank shall only become effective if the customer accepts them. Any agreement on amending a charge that concerns a payment by the consumer in excess of the charge for the principal service can only be expressly concluded with the consumer by the Bank.</p>', '302f70b2-d5cc-4ffa-aa18-283abd63bc7c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('25679da9-22c7-40e7-ae02-3d37f5f97587', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Las comisiones por los movimientos de cargos se indican en el &quot;Índice de tarifas y servicios&quot;. Toda modificación de las comisiones por los movimientos de cargo deberá ser comunicada en forma textual al cliente con una antelación mínima de dos meses con respecto a la fecha designada para que tome efecto. Si el cliente y el banco han convenido un sistema electrónico de comunicación en el ámbito de las relaciones contractuales, los cambios que se realicen también podrán ser comunicados por esa vía. Los cambios ofrecidos por el Banco solo entrarán en vigor si el Cliente los acepta. El Banco puede hacer un cambio en una remuneración que vaya más allá del pago del consumidor acordado como obligación de pago principal, solo con el acuerdo expreso del Cliente. La modificatión de comisiones pare el contrato marco del servicio de pago (contrato de giro) se rige por el número 12, inciso 5 de las Condiciones generales de Contratación.</p>', '302f70b2-d5cc-4ffa-aa18-283abd63bc7c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('eea31b16-af46-4cc0-a1f1-a8dd04d196e9', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Die Änderung von Entgelten für den Zahlungsdiensterahmenvertrag (Girovertrag) richtet sich nach Nummer 12 Absatz 5 der Allgemeinen Geschäftsbedingungen.</p>', 'ccceec63-a25d-4eb1-ad02-e2804f9a681d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ffb40c17-cc80-4414-9e7b-33119d0e61ec', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The change in charges for the payment service framework contract (current account contract) is oriented to Section 12 Paragraph 5 of the General Business Conditions.</p>', 'ccceec63-a25d-4eb1-ad02-e2804f9a681d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3ca46278-fe06-4b02-9c8f-38a8a58c5997', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p><br></p>', 'ccceec63-a25d-4eb1-ad02-e2804f9a681d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4f3efad1-3d3d-4ec1-93ac-bde3e411f05f', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>1.2.2 Entgelte für Kunden, die keine Verbraucher sind</h2>', '34e265bd-5885-4f86-99d0-09340055e6eb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f3a71e07-ab16-4572-9b0a-fd5ea8500e93', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>1.2.2 Charges for customers who are not consumers</h2>', '34e265bd-5885-4f86-99d0-09340055e6eb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8a09516f-7078-4b7c-a217-a9f87d6ddc37', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>1.2.2 Comisiones para clientes que no son consumidores</h2>', '34e265bd-5885-4f86-99d0-09340055e6eb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f7b6284a-262c-4d17-a98c-72cae3bc7fc4', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Für Entgelte und deren Änderung für Zahlungen von Kunden, die keine Verbraucher sind, verbleibt es bei den Regelungen in Nummer 12 Absätze 2 bis 6 Banken der Allgemeinen Geschäftsbedingungen.</p>', '20bb1db4-b115-4a52-915c-e2643262680a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ff6a019e-6369-4b02-bce0-048ed1f951f4', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>Charges for payments by customers and any changes in these shall continue to be governed by No. 12, paragraphs 2 – 6 of the General Business Conditions (Allgemeine Geschäftsbedingungen).</p>', '20bb1db4-b115-4a52-915c-e2643262680a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7ff2769a-18d2-4c8f-9a20-17fd364d6caa', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Para las comisiones y los cambios de las mismas en el caso de clientes que no sean consumidores, se mantienen las reclamentaciones del punto 12, incisos 2 a 6 de las Condiciones generales de Contratación de los Bancos.</p>', '20bb1db4-b115-4a52-915c-e2643262680a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3932a9ae-22d2-4240-ad9b-b319ec84af48', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2. SEPA-Basislastschrift</h2>', '76f8d79f-7072-4ff4-9cd3-f9c8877cd947');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('187baffe-de98-422f-b5bd-c294f98813e7', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2. SEPA core direct debit</h2>', '76f8d79f-7072-4ff4-9cd3-f9c8877cd947');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('eb67ace1-92f5-48f8-b5b8-9127151b0be5', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2. Notas de débito básicas SEPA</h2>', '76f8d79f-7072-4ff4-9cd3-f9c8877cd947');
