INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('82dd967f-1ef4-463b-8938-4235d54b4d18', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.1 Generalidades</h2>', 'd16ea6f9-f8d9-4cea-83ac-f2b1e9e77698');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('57a7f1b5-d259-4e2f-87b6-6aef24818ec2', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.1.1 Wesentliche Merkmale des SEPA-Basislastschriftverfahrens</h2>', '8e96dae2-9c85-45c8-a753-e5f424cac721');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('17ce338a-9880-45e4-bcb3-edef7f41ce80', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.1.1 Main characteristics of the SEPA core direct debit scheme</h2>', '8e96dae2-9c85-45c8-a753-e5f424cac721');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7e9487a8-f449-471d-a0ea-b18bd0d6bfa8', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.1.1 Características esenciales del procedimiento de notas de débito básicas SEPA</h2>', '8e96dae2-9c85-45c8-a753-e5f424cac721');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0677926e-afa8-4f59-b3a8-570bfe50075b', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Mit dem SEPA-Basislastschriftverfahren kann der Kunde über die Bank an den Zahlungsempfänger Zahlungen in Euro innerhalb des Gebiets des einheitlichen Euro-Zahlungsverkehrsraums («Single Euro Payments Area», SEPA) bewirken. Zur SEPA gehören die im Anhang genannten Staaten und Gebiete. Für die Ausführung von Zahlungen mittels SEPA-Basislastschriften muss</p>', '9796cf4a-99ea-4abe-ae0c-fbf20397abe8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2df7ea95-bcc8-450f-9b18-49c8200c79cc', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The SEPA core direct debit scheme enables the customer to make payments in euros to the payee through the Bank within the Single Euro Payments Area (SEPA). SEPA comprises the countries and territories listed in the Annex. For the execution of payments by SEPA core direct debit</p>', '9796cf4a-99ea-4abe-ae0c-fbf20397abe8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a8ce5f08-309a-494d-a6e7-663ee3bc8f64', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Con el procedimiento de notas de débito básicas SEPA, el cliente podrá realizar pagos en euros dentro de la zona única de pagos en euros (&quot;Single Euro Payments Area&quot;, SEPA) al beneficiario de pagos a través del Banco. Los países y zonas indicados en el anexo forman parte de SEPA. Para ejecutar pagos mediante notas de débito básicas SEPA</p>', '9796cf4a-99ea-4abe-ae0c-fbf20397abe8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('69cb6e56-cb4c-4a46-b28b-b4e5ab471b93', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>der Zahlungsempfänger und dessen Zahlungsdienstleister das SEPA-Basislastschriftverfahren nutzen und</li><li>der Kunde vor dem Zahlungsvorgang dem Zahlungsempfänger das SEPA-Lastschriftmandat erteilen.</li></ul>', '0694db30-5d19-4cc1-b8d1-979de07e015b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('870cf3d3-d6db-449b-b8f8-b4e37f334793', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>the payee and the payee&#39;s payment service provider must use the SEPA core direct debit scheme and</li><li>the customer must give the SEPA core direct debit mandate to the payee before the payment transaction.</li></ul>', '0694db30-5d19-4cc1-b8d1-979de07e015b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ef6ec073-1948-4b34-a121-c5ed1512794f', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>el beneficiario de pagos y su proveedor de servicios de pago deben utilizar el procedimiento de notas de débito básicas SEPA y</li><li>el cliente deberá otorgar al beneficiario de pagos el mandato de nota de débito SEPA antes de que se realice la operación de pago.</li></ul>', '0694db30-5d19-4cc1-b8d1-979de07e015b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('04270724-b127-4645-ab92-567192e8398b', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Der Zahlungsempfänger löst den jeweiligen Zahlungsvorgang aus, indem er über seinen Zahlungsdienstleister der Bank die Lastschriften vorlegt.</p>', 'c2b52e96-62d4-4e78-8bdc-1dade3f23af5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3fd7c72b-4992-4980-b0cf-39bfa98e9c5d', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The payee initiates the respective payment transaction by presenting the direct debits to the Bank through his/her payment service provider.</p>', 'c2b52e96-62d4-4e78-8bdc-1dade3f23af5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f8bdcbf8-58bd-438f-b0b9-72847700ae05', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El beneficiario del pago inicia la respectiva operación de pago presentando las notas de débito al Banco a través de su proveedor de servicios de pago.</p>', 'c2b52e96-62d4-4e78-8bdc-1dade3f23af5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d33013d7-b618-438b-9854-383d3b2f72fd', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Der Kunde kann bei einer autorisierten Zahlung aufgrund einer SEPA-Basislastschrift binnen einer Frist von acht Wochen ab dem Zeitpunkt der Belastungsbuchung auf seinem Konto von der Bank die Erstattung des belasteten Lastschriftbetrages verlangen.</p>', 'ba5147d6-2b61-401a-a11c-cbdd2673515d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3d89f7dc-a21a-49c3-94f3-4adba864fb70', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>If a payment which has been made on the basis of a SEPA core direct debit is authorised, the customer shall be entitled to claim a refund of the amount debited from the Bank. Such claim must be made within eight weeks starting from the date on which the customer&#39;s account was debited.</p>', 'ba5147d6-2b61-401a-a11c-cbdd2673515d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7df44aa3-ac3a-4b69-a46b-92859e25f221', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>En el caso de un pago autorizado en virtud de una nota de débito básica SEPA, el cliente podrá exigir del Banco, en un plazo de ocho semanas a partir del momento en que se contabilice el débito en su cuenta, el reintegro del importe de la nota de débito cargado a su cuenta.</p>', 'ba5147d6-2b61-401a-a11c-cbdd2673515d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c3f99e4a-2026-4e17-b57d-ca3af327590f', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.1.2 Kundenkennungen</h2>', '3d27e0da-1a08-47a7-8014-df178a8e2152');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fb95a4f7-1dcd-4ef2-a9f5-c7b3be62417a', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.1.2 Unique identifiers</h2>', '3d27e0da-1a08-47a7-8014-df178a8e2152');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('42a63630-6d66-40c4-afa2-704961606644', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.1.2 Identificaciones de cliente</h2>', '3d27e0da-1a08-47a7-8014-df178a8e2152');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('17e4d573-85ba-4cf9-9344-cb961dbc264c', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Für das Verfahren hat der Kunde die ihm mitgeteilte IBAN<sup>1 </sup>und bei grenzüberschreitenden Zahlungen (außerhalb des Europäischen Wirtschaftsraums<sup><a href="#footnote-2">2</a></sup>) zusätzlich den BIC<sup>3 </sup>der Bank als seine Kundenkennung gegenüber dem Zahlungsempfänger zu verwenden, da die Bank berechtigt ist, die Zahlung aufgrund der SEPA-Basislastschrift ausschließlich auf Grundlage der ihr übermittelten Kundenkennung auszuführen. Die Bank und die weiteren beteiligten Stellen führen die Zahlung an den Zahlungsempfänger an Hand der im Lastschriftdatensatz vom Zahlungsempfänger als dessen Kundenkennung angegebenen IBAN und bei grenzüberschreitenden Zahlungen außerhalb des EWR zusätzlich angegebenen BIC aus.</p>', 'd3caa712-b606-42e1-8be9-b74b88d1e416');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5dc19a01-681f-43d1-934a-49f071935253', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The customer must use the IBAN<sup>1 </sup>notified to him/her plus for crossborder payments (outside of the European Economic Area<sup><a href="#footnote-2">2</a></sup>) the BIC<sup>3 </sup>of the Bank, as his/her unique identifier vis-à-vis the payee, since the Bank is entitled to execute the payment by SEPA core direct debit solely on the basis of the unique identifier provided to it. The Bank and the intermediary institutions involved will execute the payment to the payee using the IBAN, plus for cross-border payments the BIC, indicated by the payee in the direct debit data set as the customer&#39;s unique identifier.</p>', 'd3caa712-b606-42e1-8be9-b74b88d1e416');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c6f53ab8-5acb-421c-bf5b-2aa9fbc1bc28', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Para el procedimiento el cliente deberá utilizar el código IBAN<sup>1 </sup>comunicado a él y, en los pagos transfronterizos fuera del Espacio Económico Europeo, adicionalmente, el código BIC<sup>2 </sup>del banco como su identificación de cliente frente al beneficiario del pago, puesto que el Banco está autorizado a ejecutar los pagos según las notas de débito SEPA basándose exclusivamente en las identificaciones de cliente que le son transmitidas. El Banco y las demás entidades involucradas ejecutarán el pago al beneficiario del mismo en base a los códigos IBAN, y en los pagos transfronterizos fuera del EEE, el BIC indicados por el beneficiario del pago como su identificación de cliente en el registro de datos de la nota de débito.</p>', 'd3caa712-b606-42e1-8be9-b74b88d1e416');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c42f72b4-8d6a-484b-b060-b75de829abad', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.1.3 Übermittlung von Lastschriftdaten</h2>', 'a6d8c692-d306-4647-b92c-163b4b2d184c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fcccf663-9c34-4776-8a62-9f29aba968ce', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.1.3 Transmission of direct debit data</h2>', 'a6d8c692-d306-4647-b92c-163b4b2d184c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f8f4d410-03e4-40b1-aa23-abca5d4a9ffd', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.1.3 Transmisión de datos de notas de débito</h2>', 'a6d8c692-d306-4647-b92c-163b4b2d184c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a81e53d0-78ff-4b0e-8d93-c6371c0bdf05', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Bei SEPA-Basislastschriften können die Lastschriftdaten auch über das Nachrichtenübermittlungssystem der Society for Worldwide Interbank Financial Telecommunication (SWIFT) mit Sitz in Belgien und Rechenzentren in der Europäischen Union, in der Schweiz und in den USA weitergeleitet werden.</p>', 'a21087d9-1ea3-49dc-881f-5a616744a702');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('605aa5b5-5612-4ec6-b5f1-b51ef7a0e7cf', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>When SEPA core direct debit Schemes are used, the direct debits data may be forwarded also through the message transmission system of the Society for Worldwide Interbank Financial Telecommunications (SWIFT), which is based in Belgium and has operating centres in the European Union, Switzerland and the United States.</p>', 'a21087d9-1ea3-49dc-881f-5a616744a702');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c81dd3f6-19fd-4d99-904f-07f68629915f', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>En las notas de débito básicas SEPA, el proveedor de servicios de pago del beneficiario del pago podrá transmitir al Banco los datos de las notas de débito a través del sistema de transmisión de mensajes de la Society for Worldwide Interbank Financial Telecommunication (SWIFT) con sede en Bélgica y centros de cómputo en la Unión Europea, Suiza y EE. UU.</p>', 'a21087d9-1ea3-49dc-881f-5a616744a702');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('97ac7ad0-2c0f-4b37-b54b-f57343ba841b', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.2 SEPA-Lastschriftmandat</h2>', '5008c9fc-e57c-40bd-8c30-d5d997512e09');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fefcefa2-c359-4bca-8773-d28834f26016', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.2 SEPA direct debit mandate</h2>', '5008c9fc-e57c-40bd-8c30-d5d997512e09');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6b99859d-e6c2-42a0-9112-dc7295a830c1', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.2 Mandato de nota de débito SEPA</h2>', '5008c9fc-e57c-40bd-8c30-d5d997512e09');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7d7691b7-41b9-48e9-9936-a772cd0a4c28', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.2.1 Erteilung des SEPA-Lastschriftmandats (SEPA Direct Debit Mandate)</h2>', 'd11fc3e1-c954-4d31-85cf-6563c1ee5233');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('32af7c53-aa49-4714-bcfd-0ddc52f16367', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.2.1 Filing the SEPA direct debit mandate</h2>', 'd11fc3e1-c954-4d31-85cf-6563c1ee5233');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6a42875a-bb44-4939-a703-3a35585b168d', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.2.1 Otorgamiento del mandato de nota de débito SEPA (SEPA Direct Debit Mandate)</h2>', 'd11fc3e1-c954-4d31-85cf-6563c1ee5233');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('de800ea2-3761-4a12-aa24-c7e41973b8fd', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Der Kunde erteilt dem Zahlungsempfänger ein SEPA-Lastschriftmandat. Damit autorisiert er gegenüber seiner Bank die Einlösung von SEPA-Basislastschriften des Zahlungsempfängers. Das Mandat ist schriftlich oder in der mit seiner Bank vereinbarten Art und Weise zu erteilen. In dieser Autorisierung ist zugleich die ausdrückliche Zustimmung enthalten, dass die am Lastschrifteinzug beteiligten Zahlungsdienstleister und etwaige zwischengeschaltete Stellen die für die Ausführung der Lastschrift notwendigen personenbezogenen Daten des Kunden abrufen, verarbeiten, übermitteln und speichern. In dem SEPA-Lastschriftmandat müssen die folgenden Erklärungen des Kunden enthalten sein:</p>', 'e3464268-a28a-4ca4-9150-5098d4aeac82');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e4aaa386-299a-4d67-a2b9-ace40c29e4d3', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The customer shall give a SEPA direct debit mandate to the payee. With it, the customer authorises the Bank to pay SEPA core direct debit Schemes drawn by the payee. The mandate must be given in writing or in the manner agreed with the Bank. This authorisation shall at the same time include the explicit consent that the payment service provider and possible intermediary bodies, which takes part in the direct debit collection, shall call, process, transmit and store the personal data of the customer that are necessary for the execution of the direct debit.</p>', 'e3464268-a28a-4ca4-9150-5098d4aeac82');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bcd3f8f7-7f33-4f2b-abf4-d0b171a80528', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El Cliente otorgará al beneficiario del pago un mandato de nota de débito SEPA. Con ello autoriza él a su banco a liquidar las notas de débito básicas SEPA del beneficiario del pago. El mandato deberá otorgarse por escrito o de la manera o forma acordada con el Banco. El mandato de notas de débito SEPA deberá contener las siguientes declaraciones del cliente:</p>', 'e3464268-a28a-4ca4-9150-5098d4aeac82');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9a9aa298-27a7-4ef8-bc52-d286c5eed13f', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p><br></p>', 'd26e0dff-fc6d-4dfe-81f4-111c5b84a070');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('eb78c4b4-b87e-4402-a500-2f4622a64c42', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The SEPA core direct debit mandate must contain the following statements by the customer:</p>', 'd26e0dff-fc6d-4dfe-81f4-111c5b84a070');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e153f289-6fad-47d5-b256-590662c994fa', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p><br></p>', 'd26e0dff-fc6d-4dfe-81f4-111c5b84a070');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9ad89b70-bdd6-4497-8d3a-916994b7f395', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>Ermächtigung des Zahlungsempfängers, Zahlungen vom Konto des Kunden mittels SEPA-Basislastschrift einzuziehen, und</li><li>Weisung an die Bank, die vom Zahlungsempfänger auf seiKonto gezogenen SEPA-Basislastschriften einzulösen.</li></ul>', '550dd65d-8bf3-4892-a9cd-c899b503fa76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('af3c66dc-56ed-4edd-b229-5cb410fe902f', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>a statement authorising the payee to collect payments from the customer&#39;s account by SEPA core direct debit and</li><li>a statement instructing the Bank to pay SEPA core direct debit drawn by the payee on the customer&#39;s account.</li></ul>', '550dd65d-8bf3-4892-a9cd-c899b503fa76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('07bf997b-ef16-4018-a18b-dd69c8c94983', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>autorización otorgada al beneficiario del pago para cobrar pagos de la cuenta del cliente mediante notas de débito básicas SEPA e</li><li>instrucciones al Banco para que liquide las notas de débito básicas SEPA giradas por el beneficiario del pago sobre la cuenta del cliente.</li></ul>', '550dd65d-8bf3-4892-a9cd-c899b503fa76');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e3d6a951-981e-423c-b974-abbc8b308937', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Das SEPA-Lastschriftmandat muss folgende Autorisierungsdaten enthalten:</p>', '7c7d6414-f0dc-4ac3-ac56-b6689443d333');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a436ac37-2819-4e64-a22b-19f546743f39', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The SEPA core direct debit mandate must contain the following authorisation data:</p>', '7c7d6414-f0dc-4ac3-ac56-b6689443d333');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('69cab919-4853-4299-995d-1732326b423e', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El mandato de nota de débito básica SEPA deberá contener los siguientes datos de autorización:</p>', '7c7d6414-f0dc-4ac3-ac56-b6689443d333');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8c744b59-3ec7-47af-87cf-8094dfcba43d', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>Bezeichnung des Zahlungsempfängers,</li><li>eine Gläubigeridentifikationsnummer,</li><li>Kennzeichnung als einmalige oder wiederkehrende Zahlung,</li><li>Name des Kunden (sofern verfügbar),</li><li>Bezeichnung der Bank des Kunden und</li><li>seine Kundenkennung (siehe Nummer 2.1.2).</li></ul>', '934ac015-8a5c-47d4-b387-90d6e2883bbf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2cd34379-6b81-490a-963a-2650fbfa4b87', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>identification of the payee</li><li>creditor identifier</li><li>indication of whether the mandate is for a one-off or recurrent payment</li><li>name of the customer (if available)</li><li>name of the customer&#39;s bank and</li><li>customer&#39;s unique identifier (see Section 2.1.2).</li></ul>', '934ac015-8a5c-47d4-b387-90d6e2883bbf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e8c96c35-5d87-4d45-b209-d50cc54b4f13', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>denominación del beneficiario del pago,</li><li>un número de identificación de acreedor,</li><li>identificativo de pago único o pago recurrente,</li><li>nombre del cliente,</li><li>nombre del banco del cliente y</li><li>su identificación de cliente (ver el punto 2.1.2).</li></ul>', '934ac015-8a5c-47d4-b387-90d6e2883bbf');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('62856192-f5fd-4163-9b96-3447db107f14', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Über die Autorisierungsdaten hinaus kann das Lastschriftmandat zusätzliche Angaben enthalten.</p>', 'd3b835f1-1b2e-4f6e-86c1-d71da84d44a5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2f54ba6f-ca27-44d7-858c-886b8cdde3f6', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The direct debit mandate may contain additional details supplementing the authorisation data.</p>', 'd3b835f1-1b2e-4f6e-86c1-d71da84d44a5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a3efa983-ab3d-4802-b3af-9f3b5d8c3b3a', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Aparte de los datos de la autorización, el mandato de nota de débito podrá contener información adicional.</p>', 'd3b835f1-1b2e-4f6e-86c1-d71da84d44a5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c2f724f5-99f9-46e3-a159-19ff0aa6c3bf', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.2.2 Einzugsermächtigung als SEPA-Lastschriftmandat</h2>', '8e920918-3616-4ecd-bed0-9995df767c53');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9f9a156d-8f2c-471b-a0d9-900215742e8e', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.2.2 Collection authorisation (Einzugsermächtigung) as a SEPA direct debit mandate</h2>', '8e920918-3616-4ecd-bed0-9995df767c53');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5289da0d-2fe9-4642-b145-f50e86e0a72e', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.2.2 Autorización de cobro en forma de mandato de nota de débito SEPA</h2>', '8e920918-3616-4ecd-bed0-9995df767c53');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('183c2a13-9a70-4377-952d-281bbe8ec398', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Hat der Kunde dem Zahlungsempfänger eine Einzugsermächtigung erteilt, mit der er den Zahlungsempfänger ermächtigt, Zahlungen von seinem Konto mittels Lastschrift einzuziehen, weist er zugleich damit die Bank an, die vom Zahlungsempfänger auf sein Konto gezogenen Lastschriften einzulösen. Mit der Einzugsermächtigung autorisiert der Kunde gegenüber seiner Bank die Einlösung von Lastschriften des Zahlungsempfängers. Diese Einzugsermächtigung gilt als SEPA-Lastschriftmandat. Sätze 1 bis 3 gelten auch für vom Kunden vor dem Inkrafttreten dieser Bedingungen erteilte Einzugsermächtigungen.</p>', 'e41898fe-edf9-4660-b224-748ffddae1c7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('72613210-d173-4dbc-9d87-f5240f0fcfec', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>If the customer has given collection authorisation (Einzugsermächtigung) to the payee, authorising the payee to collect payments from his/ her account by direct debit, the customer thereby instructs the Bank at the same time to pay the direct debits drawn on his/her account by the payee. With the collection authorisation, the customer authorises the Bank to pay direct debits drawn by the payee. This collection authorisation shall be deemed to be a SEPA direct debit mandate. Sentences 1 – 3 shall apply also to collection authorisation given by the customer prior to the entry into force of these Terms and Conditions.</p>', 'e41898fe-edf9-4660-b224-748ffddae1c7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('24d89152-a23b-4717-8014-3b0a60db0aa0', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Cuando el cliente otorga al beneficiario de pagos una autorización de cobro que permite a éste cobrar pagos de la cuenta del cliente mediante notas de débito, da con ello al mismo tiempo instrucciones al Banco para que liquide las notas de débito giradas por el beneficiario de pagos sobre la cuenta del cliente. Con la autorización de cobro el cliente autoriza a su banco a liquidar las notas de débito del beneficiario de pagos. Esa autorización de cobro se considera un mandato de nota de débito SEPA Las oraciones 1 a 3 rigen también para las autorizaciones de cobro otorgadas por el cliente antes de entrar en vigencia las presentes condiciones.</p>', 'e41898fe-edf9-4660-b224-748ffddae1c7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('43b42239-0181-423a-b6ec-633b2425d255', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Die Einzugsermächtigung muss folgende Autorisierungsdaten enthalten:</p>', '9dfde25d-bea5-4db7-9609-ac65568abcee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3df630d5-960f-4989-9cda-d59830586990', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>Collection authorisation must contain the following authorisation data:</p>', '9dfde25d-bea5-4db7-9609-ac65568abcee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b5ac065f-c5d5-4988-9325-3db134c2aa87', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>La autorización de cobro deberá contener los siguientes datos de autorización:</p>', '9dfde25d-bea5-4db7-9609-ac65568abcee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('762adca2-930c-413e-a928-a135b91da826', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>Bezeichnung des Zahlungsempfängers,</li><li>Name des Kunden,</li><li>Kundenkennung nach Nummer 2.1.2 oder Kontonummer und Bankleitzahl des Kunden.</li></ul>', '0a0861f6-1322-4b1b-83cd-a07ecc5b2da1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('79eeffb1-46f4-46ba-898e-12128d58b352', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>name and address of the payee</li><li>name of the customer</li><li>customer&#39;s unique identifier in accordance with Section 2.1.2 or account number (Kontonummer) and bank code (Bankleitzahl).</li></ul>', '0a0861f6-1322-4b1b-83cd-a07ecc5b2da1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a08f6b01-1767-4c42-b942-d10d67e0aa89', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>denominación del beneficiario del pago,</li><li>nombre del cliente,</li><li>identificación de cliente según el punto 2.1.2 o número de cuenta y código bancario del cliente.</li></ul>', '0a0861f6-1322-4b1b-83cd-a07ecc5b2da1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e606a44c-12a5-42f8-844e-e6f1fd7b5e2a', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Über die Autorisierungsdaten hinaus kann die Einzugsermächtigung zusätzliche Angaben enthalten.</p>', 'c0e2e60f-a3e6-46c1-a711-e0ac3171b95b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2e27ce9b-fe5d-4c9b-bb3d-f460ad57c6d5', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>Collection authorisation may contain additional details supplementing the authorisation data.</p>', 'c0e2e60f-a3e6-46c1-a711-e0ac3171b95b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0d1ffe35-a505-4582-b970-b9d1a3170fa5', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Aparte de los datos de la autorización, la autorización de cobro podrá contener información adicional.</p>', 'c0e2e60f-a3e6-46c1-a711-e0ac3171b95b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4267770d-8f24-451e-a43e-5b9d64b747ba', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.2.3 Widerruf des SEPA-Lastschriftmandats</h2>', '8e035641-eaf3-49a3-afd3-0e1354d27972');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('19918f09-c8a9-4ff7-8196-e362b35b80ab', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.2.3 Revocation the SEPA direct debit mandate</h2>', '8e035641-eaf3-49a3-afd3-0e1354d27972');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('42c0a440-abb7-4599-9abd-11ce45fefbd4', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.2.3 Revocación del mandato de nota de débito SEPA</h2>', '8e035641-eaf3-49a3-afd3-0e1354d27972');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b9357c86-cb87-4934-a9ae-18d4cd00a8f3', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Das SEPA-Lastschriftmandat kann vom Kunden durch Erklärung gegenüber dem Zahlungsempfänger oder seiner Bank – möglichst schriftlich – mit der Folge widerrufen werden, dass nachfolgende Zahlungsvorgänge nicht mehr autorisiert sind. Erfolgt der Widerruf gegenüber der Bank, wird dieser ab dem auf den Eingang des Widerrufs folgenden Geschäftstag gemäß «Preis- und Leistungsverzeichnis» wirksam. Zusätzlich sollte dieser auch gegenüber dem Zahlungsempfänger erklärt werden, damit dieser keine weiteren Lastschriften einzieht.</p>', '76894775-aa8c-4994-aece-37cf7860050e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('db1f8299-aa01-43b9-8ca7-38bb1957951e', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The SEPA direct debit mandate may be revoked by the customer by means of a statement to this effect – if possible, in writing – to the payee or the Bank, with the result that subsequent payment transactions are no longer authorised. If notice of revocation is given to the Bank, it shall take effect from the banking business day, as stated in the &quot;List of Prices and Services&quot;, following the day on which it is received. Notice of revocation should, in addition, be given to the payee so that the payee does not collect any further direct debits.</p>', '76894775-aa8c-4994-aece-37cf7860050e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1778d263-febe-4778-bcce-cd50854723f6', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El cliente podrá revocar el mandato de nota de débito SEPA presentando la revocación respectiva, en lo posible escrita, ante el proveedor de servicios de pago o ante su Banco, con la consecuencia de que las operaciones de pago siguientes ya no estarán autorizadas. Cuando la revocación se presenta al Banco, entrará en vigencia a partir del día hábil posterior a su recepción, de conformidad con el &quot;Índice de precios y servicios&quot;. Adicionalmente, también deberá enviarse la declaración de revocación al beneficiario de pagos, para que no cobre más notas de débito.</p>', '76894775-aa8c-4994-aece-37cf7860050e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7d45094f-0170-49d6-bc94-098e9363c483', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.2.4 Begrenzung und Nichtzulassung von SEPA-Basislastschriften</h2>', 'e3dd6314-6467-4175-ae6b-6ebc38627d2f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e739c008-f8c9-413a-92f2-35b8a05aa35e', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.2.4 Limitation and disallowance of SEPA core direct debits</h2>', 'e3dd6314-6467-4175-ae6b-6ebc38627d2f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ab4928a6-0c76-41af-81a2-29bfc77bbc4d', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.2.4 Rechazo de notas de débito básicas SEPA individuales</h2>', 'e3dd6314-6467-4175-ae6b-6ebc38627d2f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('996d2851-1abf-473b-89aa-3e7cde3d9916', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Der Kunde kann der Bank gesondert die Weisung erteilen, Zahlungen aus SEPA-Basislastschriften zu begrenzen oder nicht zuzulassen. Diese Weisung muss der Bank bis spätestens zum Ende des Geschäftstages gemäß «Preis- und Leistungsverzeichnis» vor dem im Datensatz der Lastschrift angegebenen Fälligkeitstag zugehen. Diese Weisung sollte möglichst schriftlich und möglichst gegenüber der kontoführenden Stelle der Bank erfolgen. Zusätzlich sollte diese auch gegenüber dem Zahlungsempfänger erklärt werden.</p>', '0f5351e1-39a2-4cc4-9185-eae8343cc640');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5f9dbb10-da62-4889-b9d7-ce45c3d776f0', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The customer may separately instruct the Bank to limit or disallow payments under SEPA core direct debits. This instruction must be received by the Bank no later than the end of the banking business day, as stated in the &quot;List of Prices and Services&quot;, before the due date indicated in the direct debit data set. This instruction should, if possible, be given in writing and to the account-keeping branch of the Bank. It should, in addition, be given to the payee.</p>', '0f5351e1-39a2-4cc4-9185-eae8343cc640');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b60fad8f-8bc4-4b57-b0e1-8cd495136aa6', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El cliente puede dar instrucciones especiales al Banco para que no liquide notas de débito básicas SEPA específicas del beneficiario de pagos. El Banco debe recibir esas instrucciones a más tardar hacia el final del día hábil anterior a la fecha de vencimiento indicada en el registro de datos de la nota de débito, tal y como se define en el &quot;Índice de precios y servicios&quot;. Siempre que sea posible las instrucciones deben darse por escrito y presentarse directamente a las oficinas del Banco donde se mantiene la cuenta del cliente. Adicionalmente se debería informar al beneficiario del pago al respecto.</p>', '0f5351e1-39a2-4cc4-9185-eae8343cc640');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('08efe472-9574-463a-acbb-88e440b4b75c', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.3 Einzug der SEPA-Basislastschrift auf Grundlage des SEPA-Lastschriftmandats durch den Zahlungsempfänger</h2>', 'c0dfd349-83c8-4238-8074-495025ca8cc9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8ba25730-a0b5-4a27-a42b-ec182badd6c9', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.3 Collection of the SEPA core direct debit by the payee under the SEPA core direct debit mandate</h2>', 'c0dfd349-83c8-4238-8074-495025ca8cc9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('bea5bfe9-cd96-4fb9-845f-e5fc68cc921b', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.3 Cobro de la nota de débito básica SEPA en base al mandato de nota de débito SEPA por parte del beneficiario de pagos</h2>', 'c0dfd349-83c8-4238-8074-495025ca8cc9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('aed0c665-3083-45bc-8a8b-a39bc6baa128', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>1 Das vom Kunden erteilte SEPA-Lastschriftmandat verbleibt beim Zahlungsempfänger. Dieser übernimmt die Autorisierungsdaten und setzt etwaige zusätzliche Angaben in den Datensatz zur Einziehung von SEPA-Basislastschriften. Der jeweilige Lastschriftbetrag wird vom Zahlungsempfänger angegeben.</p>', '351b7fc7-5a23-437c-b8c1-ccb9879b150b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('219a0a13-24b4-4447-b8fc-d37d6aa123af', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>1 The SEPA core direct debit mandate given by the customer shall remain with the payee. The payee shall take over the authorisation data and enter any additional details in the data set for collection of SEPA core direct debits. The respective direct debit amount shall be specified by the payee.</p>', '351b7fc7-5a23-437c-b8c1-ccb9879b150b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d19af8ef-5f63-49f6-b66d-91bc8350a8d4', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>1 El mandato de nota de débito SEPA otorgado por el cliente queda en poder del beneficiario del pago. Este incluye los datos de autorización y eventuales datos adicionales en el registro de datos para el cobro de notas de débito básicas SEPA. El beneficiario del pago indicará el importe de la respectiva nota de débito.</p>', '351b7fc7-5a23-437c-b8c1-ccb9879b150b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8b94400c-f4fa-4852-bd11-73568a3f65d5', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>2 Der Zahlungsempfänger übermittelt elektronisch den Datensatz zur Einziehung der SEPA-Basislastschrift unter Einschaltung seines Zahlungsdienstleisters an die Bank als Zahlstelle. Dieser Datensatz verkörpert auch die Weisung des Kunden an die Bank zur Einlösung der jeweiligen SEPA-Basislastschrift (siehe Nummer 2.2.1 Sätze 2 und 4 beziehungsweise Nummer 2.2.2 Satz 2). Für den Zugang dieser Weisung verzichtet die Bank auf die für die Erteilung des SEPA-Lastschriftmandats vereinbarte Form (siehe Nummer 2.2.1 Satz 3).</p>', '8e87f03f-f588-40ea-bab0-9858311256d8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('493c4058-a59d-4031-8f17-d4fa63827232', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>2 The payee shall send the data set for collection of the SEPA core direct debit to the Bank (payer bank) electronically through his/her payment service provider. This data set shall also represent the customer&#39;s instruction to the Bank in the SEPA direct debit mandate to pay the respective SEPA core direct debit (see Section 2.2.1, sentences 2 and 4 and Section 2.2.2, sentence 2). For delivery of this instruction, the Bank shall waive the form agreed for giving the SEPA direct debit mandate (see Section 2.2.1, sentence 3).</p>', '8e87f03f-f588-40ea-bab0-9858311256d8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0e6bd402-8229-4d30-a836-bc5ca55b2019', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>2 El beneficiario del pago transmite electrónicamente al Banco, como agente pagador, el registro de datos para cobrar la nota de débito básica SEPA, sirviéndose para ello de su proveedor de servicios de pago. Ese registro de datos constituye también implícitamente la instrucción del cliente al Banco, incluida en el mandato de nota de débito SEPA, para que liquide la respectiva nota de débito básica SEPA (véase el punto 2.2.1 oraciones 2 y 4 y el punto 2.2.2 oración 2). Para la recepción de esta instrucción el Banco desiste de la forma acordada para el otorgamiento del mandato de nota de débito SEPA (ver el punto 2.2.1 oración 3).</p>', '8e87f03f-f588-40ea-bab0-9858311256d8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8b8f4cfc-921b-459a-bc2d-8cb83ffa35e6', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.4 Zahlungsvorgang aufgrund der SEPA-Basislastschrift</h2>', '40561b0c-ea65-477b-9ee8-b0eb12f2c302');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('50c7aede-e9c2-4fab-81dc-8d86a77a03f2', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.4 Payment transaction based on the SEPA Core Direct Debit Scheme</h2>', '40561b0c-ea65-477b-9ee8-b0eb12f2c302');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('02d3a06a-73f7-4848-ad41-1d11375fe23b', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.4 Operación de pago en base a la nota de débito básica SEPA</h2>', '40561b0c-ea65-477b-9ee8-b0eb12f2c302');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('78c38c7e-ac6e-4c0d-880a-1adce7645454', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.4.1 Belastung des Kontos des Kunden mit dem Lastschriftbetrag</h2>', '172a0476-9bd3-4397-bd8e-0a65c5d99556');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('587cde4f-0993-48cf-82b4-255683437c8e', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.4.1 Debiting the direct debit amount to the customer&#39;s account</h2>', '172a0476-9bd3-4397-bd8e-0a65c5d99556');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('58f39b85-4956-4b08-af22-2f4ec8502a59', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.4.1 Cargo del importe de la nota de débito a la cuenta del cliente</h2>', '172a0476-9bd3-4397-bd8e-0a65c5d99556');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a353d3b8-bcea-4f40-9960-09eb8999030c', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>1 Eingehende SEPA-Basislastschriften des Zahlungsempfängers werden am im Datensatz angegebenen Fälligkeitstag mit dem vom Zahlungsempfänger angegebenen Lastschriftbetrag dem Konto des Kunden belastet. Fällt der Fälligkeitstag nicht auf einen im «Preis- und Leistungsverzeichnis» ausgewiesenen Geschäftstag der Bank, erfolgt die Kontobelastung am nächsten Geschäftstag.</p>', '7681db8b-9235-4bd8-9fc8-ee591e6eb946');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('80189054-a76c-4b25-8ad7-f760d75acc8b', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>1 On receipt of SEPA core direct debit schemes drawn by the payee, the amount specified by the payee shall be debited to the customer&#39;s account on the due date indicated in the direct debit data set. If the due date is not a banking business day as stated in the &quot;Schedule of prices and services&quot;, the account shall be debited on the next banking business day.</p>', '7681db8b-9235-4bd8-9fc8-ee591e6eb946');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cc3a6f82-ce46-4123-b912-7b4134d799f5', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>1 Las notas de débito básicas SEPA recibidas del beneficiario de pagos se cargan a la cuenta del cliente en la fecha de vencimiento indicada en el registro de datos, debitando el importe de la nota de débito indicado por el beneficiario de pagos. Si la fecha de vencimiento no es un día hábil según el &quot;Índice de precios y servicios&quot; del Banco, el cargo en la cuenta se realiza el día hábil siguiente.</p>', '7681db8b-9235-4bd8-9fc8-ee591e6eb946');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('eeeef6e8-90c5-4f52-9e0f-d64333b00d1d', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>2 Eine Kontobelastung erfolgt nicht oder wird spätestens am zweiten Bankarbeitstag<sup>4 </sup>nach ihrer Vornahme rückgängig gemacht (siehe Nummer 2.4.2), wenn</p>', '0bde7bbd-604b-4404-bc0d-ac424dbf30c7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fbe79ae7-1353-440f-baec-6fdd09a3c4af', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>2 The customer&#39;s account shall not be debited or a debit entry shall be cancelled no later than the second bank working day<sup>4 </sup>after it was made (see Section 2.4.2) if</p>', '0bde7bbd-604b-4404-bc0d-ac424dbf30c7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('701cf5cb-41d7-4e5a-a7c0-02bb891e977f', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>2 No se realizará ningún cargo en cuenta o se anulará a lo sumo el segundo día hábil tras su ejecución (ver el punto 2.4.2), cuando</p>', '0bde7bbd-604b-4404-bc0d-ac424dbf30c7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d83792fa-2e14-4cef-9075-81d523cfe53c', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>der Bank ein Widerruf des SEPA-Lastschriftmandats gemäß Nummer 2.2.3 zugegangen ist,</li><li>der Kunde über kein für die Einlösung der Lastschrift ausreichendes Guthaben auf seinem Konto oder über keinen ausreichenden Kredit verfügt (fehlende Kontodeckung); Teileinlösungen nimmt die Bank nicht vor,</li><li>die im Lastschriftdatensatz angegebene IBAN des Zahlungspflichtigen keinem Konto des Kunden bei der Bank zuzuordnen ist oder</li><li>die Lastschrift nicht von der Bank verarbeitbar ist, da im Lastschriftdatensatz<ul><li>eine Gläubigeridentifikationsnummer fehlt oder für die Bank erkennbar fehlerhaft ist,</li><li>eine Mandatsreferenz fehlt,</li><li>ein Ausstellungsdatum des Mandats fehlt oder</li><li>kein Fälligkeitstag angegeben ist.</li><li></li></ul></li></ul>', '3814c263-4a9f-45e6-93ec-928952d8434e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('754e5ce7-3900-454c-a436-6d8c1ebb4785', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>the Bank has received notice of revocation of the SEPA direct debit mandate pursuant to Section 2.2.3</li><li>the customer does not have a sufficient credit balance on the account or sufficient credit for payment of the direct debit (lack of funds); the Bank shall not pay partial amounts,</li><li>the payer&#39;s IBAN indicated in the direct debit data set cannot be assigned to any account held by the customer with the Bank or</li><li>the direct debit cannot be processed by the Bank because the direct debit data set<ul><li>does not contain a creditor identifier or contains one which is evidently wrong to the Bank</li><li>does not contain a mandate reference</li><li>does not indicate the date on which the mandate was given or</li><li>does not indicate the due date.</li><li></li></ul></li></ul>', '3814c263-4a9f-45e6-93ec-928952d8434e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('93db2381-cd54-4cc2-b8aa-86efb6550b5c', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>el Banco haya recibido una revocación del mandato de nota de débito SEPA según el punto 2.2.3,</li><li>el Banco haya recibido un rechazo de la nota de débito del cliente según el punto 2.2.4,</li><li>el cliente no disponga en su cuenta de fondos suficientes o de crédito suficiente para la liquidación de la nota de débito (cobertura insuficiente de la cuenta); el Banco no realiza pagos parciales,</li><li>el IBAN indicado en el registro de datos de la nota de débito no se pueda asignar a ninguna cuenta del cliente en el Banco o<ul><li>el Banco no pueda procesar la nota de débito debido a que en el registro de datos de la nota de débito</li><li>falte el número de identificación de acreedor o el Banco lo reconozca como incorrecto,</li><li>falte una referencia de mandato,</li><li>falte una fecha de emisión de mandato o</li><li>no se haya indicado ninguna fecha de vencimiento.</li></ul></li></ul>', '3814c263-4a9f-45e6-93ec-928952d8434e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('10c5c4bf-aab5-4cf4-8e8a-827100198482', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>3 Darüber hinaus erfolgt eine Kontobelastung nicht oder wird spätestens am zweiten Bankarbeitstag nach ihrer Vornahme rückgängig gemacht (siehe Nummer 2.4.2), wenn dieser SEPA-Basislastschrift eine gesonderte Weisung des Kunden nach Nummer 2.2.4 entgegensteht.</p>', 'defcaa8e-d1ff-43df-b018-9b8e4ae94b18');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('78df5e74-3d06-492f-a471-9816e4f1ab07', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>3 In addition, the customer&#39;s account shall not be debited or a debit entry shall be cancelled no later than the second bank working day after it was made (see Section 2.4.2) if this SEPA core direct debit is countermanded by a separate instruction from the customer pursuant to Section 2.2.4.</p>', 'defcaa8e-d1ff-43df-b018-9b8e4ae94b18');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('37ab496e-fb10-47f1-a114-afb0369db656', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p><br></p>', 'defcaa8e-d1ff-43df-b018-9b8e4ae94b18');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b4d50030-619c-4440-a962-673c20961699', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.4.2 Einlösung von SEPA-Basislastschriften</h2>', '542dd3a7-5193-482a-a10d-ef0d61703799');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9394cdd8-d7ad-4cab-9278-b834fcce948a', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.4.2 Payment of SEPA core direct debits</h2>', '542dd3a7-5193-482a-a10d-ef0d61703799');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5f53fccc-0bd8-4baa-98d5-25ae9968d32f', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.4.2 Liquidación de notas de débito básicas SEPA</h2>', '542dd3a7-5193-482a-a10d-ef0d61703799');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('44d11d67-c0f8-48a0-aa93-d25b6c8261bb', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>SEPA-Basislastschriften sind eingelöst, wenn die Belastungsbuchung auf dem Konto des Kunden nicht spätestens am zweiten Bankarbeitstag nach ihrer Vornahme rückgängig gemacht wird.</p>', '8cd40110-9873-4f17-8b0b-f377e1c30b72');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('00233ac4-c09b-4bd9-9fd1-46e0f7ab9923', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>SEPA core direct debits are paid if the debit entry in the customer&#39;s account has not been cancelled later than the second bank working day after it was made.</p>', '8cd40110-9873-4f17-8b0b-f377e1c30b72');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1da08599-154f-45c6-8766-c2bbea7b3513', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Las notas de débito básicas SEPA se considerarán liquidadas cuando la contabilización del débito de la cuenta del cliente no se haya sido anulada a más tardar el segundo día hábil tras su ejecución según el &quot;Índice de precios y servicios&quot;.</p>', '8cd40110-9873-4f17-8b0b-f377e1c30b72');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('254fa4bb-a1b8-4730-bbda-e6715b20a63d', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.4.3 Unterrichtung über die Nichtausführung oder Rückgängigmachung der Belastungsbuchung oder Ablehnung der Einlösung</h2>', '9156ce2e-1942-42ab-8fa9-505534d4432b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a0d630e6-de43-43f7-a6c9-5fcfa47b7a9e', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.4.3 Notification of non-execution or cancellation of the debit entry or refusal of payment</h2>', '9156ce2e-1942-42ab-8fa9-505534d4432b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9abf3a54-fee3-4e1d-ab73-d783135f83ff', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.4.3 Información sobre la falta de ejecución o la anulación de la contabilización de débito o rechazo de liquidación</h2>', '9156ce2e-1942-42ab-8fa9-505534d4432b');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f95bff73-85a9-4cdb-b7b7-28e8e5e7b3c5', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Über die Nichtausführung oder Rückgängigmachung der Belastungsbuchung (siehe Nummer 2.4.1 Absatz 2) oder die Ablehnung der Einlösung einer SEPA-Basislastschrift (siehe Nummer 2.4.2) wird die Bank den Kunden unverzüglich, spätestens bis zu der gemäß Nummer 2.4.4 vereinbarten Frist unterrichten. Dies kann auch auf dem für Kontoinformationen vereinbarten Weg geschehen. Dabei wird die Bank, soweit möglich, die Gründe sowie die Möglichkeiten angeben, wie Fehler, die zur Nichtausführung, Rückgängigmachung oder Ablehnung geführt haben, berichtigt werden können. Für die berechtigte Ablehnung der Einlösung einer autorisierten SEPA-Basislastschrift wegen fehlender Kontodeckung (siehe Nummer 2.4.1 Absatz 2 zweiter Spiegelstrich) berechnet die Bank das im «Preis- und Leistungsverzeichnis» ausgewiesene Entgelt.</p>', '3bdc3339-bd44-4e2d-b38b-a4539f60c12d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dc01896a-7e06-40ed-95c3-03abe97cffcf', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The Bank shall inform the customer without delay, and no later than the time agreed in Section 2.4.4, of non-execution or cancellation of the debit entry (see Section 2.4.1, paragraph 2) or refusal to pay a SEPA core direct debit (see Section 2.4.2). This may be done also through the agreed account information channel. The Bank shall, if possible, state the reasons and indicate ways in which errors that led to  the non-execution, cancellation or refusal can be rectified. For a justified refusal to pay an authorised SEPA core direct debit due to a lack of funds (see Section 2.4.1, paragraph 2, second bullet point, the Bank shall levy the charge set out in the &quot;List of Prices and Services&quot;.</p>', '3bdc3339-bd44-4e2d-b38b-a4539f60c12d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('80a5c0be-fa39-47c5-9a3f-c4db282ac684', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El Banco informará al cliente de inmediato o, a lo sumo, en el plazo acordado en el punto 2.4.4 acerca de la falta de ejecución o la anulación de la contabilización de débito por nota de débito o el rechazo de la liquidación de una nota de débito básica SEPA. Esto también podrá realizarse por la vía acordada para la información de la cuenta. En este contexto el Banco indicará, en la medida posible, los motivos así como las maneras de corregir los errores que hayan dado lugar a la falta de ejecución, anulación o rechazo. Al consumo en el plazo de ejecución especificado el Banco cobra la comisión que se especifica en el &quot;Índice de precios y servicios&quot;.</p>', '3bdc3339-bd44-4e2d-b38b-a4539f60c12d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9e8b6ba2-8cbc-4541-882b-479bedb8d353', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.4.4 Ausführung der Zahlung</h2>', 'ee06b83b-0b1f-4171-bb41-8114ad9aa5c8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('58e893af-180e-4382-be95-71ffd4a7a03a', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.4.4 Execution of the payment</h2>', 'ee06b83b-0b1f-4171-bb41-8114ad9aa5c8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('df71aa2c-852a-4aa5-82e3-a46f3ac948c0', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.4.4 Ejecución del pago</h2>', 'ee06b83b-0b1f-4171-bb41-8114ad9aa5c8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d61bd616-b787-443f-9d5c-7c4fa48c1699', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>1 Die Bank ist verpflichtet sicherzustellen, dass der von ihr dem Konto des Kunden aufgrund der SEPA-Basislastschrift des Zahlungsempfängers belastete Lastschriftbetrag spätestens innerhalb der im «Preis- und Leistungsverzeichnis» angegebenen Ausführungsfrist beim Zahlungsdienstleister des Zahlungsempfängers eingeht.</p>', '6f6f6caf-22c0-4b2f-a623-5f2b7e21f854');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ea115eba-0311-4f74-8efd-25dac99be28a', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>1 The Bank must ensure that the direct debit amount debited to the customer&#39;s account on the basis of the SEPA core direct debit of the payee reaches the payment service provider of the payee no later than within the execution period indicated in the &quot;Schedule of prices and services&quot;.</p>', '6f6f6caf-22c0-4b2f-a623-5f2b7e21f854');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('018e57a1-200b-4018-b1d5-6bdf57a487b1', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El Banco está obligado a garantizar que el proveedor de servicios de pago del beneficiario de pagos reciba, a lo sumo en el plazo de ejecución especificado en el &quot;índice de precios y servicios&quot;, el importe de la nota de débito cargado a la cuenta del cliente en base a la nota de débito básica SEPA girada por el beneficiario de pagos.</p>', '6f6f6caf-22c0-4b2f-a623-5f2b7e21f854');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7728e2b4-ec0d-4d58-a840-7446ed0090a8', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>2 Die Ausführungsfrist beginnt an dem im Lastschriftdatensatz angegebenen Fälligkeitstag. Fällt dieser Tag nicht auf einen Geschäftstag gemäß «Preis- und Leistungsverzeichnis» der Bank, so beginnt die Ausführungsfrist am darauf folgenden Geschäftstag.</p>', '5e1cb07c-93a0-4e4d-b89a-b5d1cb019aed');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8965713f-7ab8-4029-8079-ad7de1188821', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>2 The execution period shall commence on the due date indicated in the direct debit data set. If this date is not a banking business day as stated in the &quot;Schedule of prices and services&quot;, the execution period shall commence on the following banking business day.</p>', '5e1cb07c-93a0-4e4d-b89a-b5d1cb019aed');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b051274a-061f-480e-8098-b20f20a8c656', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>2 El plazo de ejecución empieza en la fecha de vencimiento indicado en el registro de datos de la nota de débito. Si esa fecha no es un día hábil según el &quot;Índice de precios y servicios&quot; del Banco, el plazo de ejecución empezará el día hábil siguiente.</p>', '5e1cb07c-93a0-4e4d-b89a-b5d1cb019aed');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('af0b6170-1f61-4b0b-961b-aeb717468f75', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>3 Die Bank unterrichtet den Kunden über die Ausführung der Zahlung auf dem für Kontoinformationen vereinbarten Weg und in der vereinbarten Häufigkeit.</p>', 'ae9e605e-b8bf-42d2-ad65-657ddc646c69');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d1b60659-92d1-4773-87b8-d86a830fa382', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>3 The Bank shall inform the customer of the execution of the payment through the agreed account information channel and at the agreed frequency.</p>', 'ae9e605e-b8bf-42d2-ad65-657ddc646c69');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fdbf61af-649f-461b-bbbd-6077ca446176', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El Banco informará al cliente sobre la ejecución del pago por la vía de información de cuenta acordada y con la frecuencia convenida.</p>', 'ae9e605e-b8bf-42d2-ad65-657ddc646c69');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3dd66cdd-741a-4524-842b-6ea0a6a1f291', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.5 Erstattungsanspruch des Kunden bei einer autorisierten Zahlung</h2>', '128bf9ff-7b9a-4862-beca-56628ce535b7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('56de01d9-7071-4880-bd8f-dd32b3248d4d', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.5 Customer&#39;s entitlement to a refund for an authorised payment</h2>', '128bf9ff-7b9a-4862-beca-56628ce535b7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('295c7d21-7780-4403-96a0-a576cfb4dd70', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.5 Derecho de reintegro del cliente en caso de un pago autorizado</h2>', '128bf9ff-7b9a-4862-beca-56628ce535b7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ca64510c-15e7-4d90-892e-12b9b802b116', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>1 Der Kunde kann bei einer autorisierten Zahlung aufgrund einer SEPA-Basislastschrift binnen einer Frist von acht Wochen ab dem Zeitpunkt der Belastungsbuchung auf seinem Konto von der Bank ohne Angabe von Gründen die Erstattung des belasteten Lastschriftbetrages verlangen. Dabei bringt sie das Konto wieder auf den Stand, auf dem es sich ohne die Belastung durch die Zahlung befunden hätte. Etwaige Zahlungsansprüche des Zahlungsempfängers gegen den Kunden bleiben hiervon unberührt.</p>', 'ceba15df-ceef-457c-b247-6026a73a45be');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('510026fe-b8fc-4b22-b9bf-788510891987', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>1 If a payment which has been made on the basis of a SEPA core direct debit is authorised, the customer shall be entitled to claim a no-questions-asked refund of the amount debited from the Bank. Such claim must be made within eight weeks starting from the date on which the customer&#39;s account was debited. The Bank shall restore the balance of the customer&#39;s account to what it would have been without debiting for the payment. Any claims by the payee against the customer shall not be affected by this.</p>', 'ceba15df-ceef-457c-b247-6026a73a45be');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3d52d3f0-3167-4835-9de0-7ff66717d5f9', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>2 En el caso de un pago autorizado en virtud de una nota de débito básica SEPA, el cliente podrá exigir del Banco, en un plazo de ocho semanas a partir del momento en que se contabilice el débito en su cuenta, el reintegro del importe de la nota de débito cargado a su cuenta sin necesidad de indicar motivos. El Banco deberá reponer el estado de la cuenta en el estado que tendría si no se hubiera realizado el cargo del pago. Esto no influirá sobre los derechos a pago que el beneficiario de pagos tenga frente al cliente.</p>', 'ceba15df-ceef-457c-b247-6026a73a45be');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3c67e414-afc6-4533-a3c2-1c2552b054da', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>2 Der Erstattungsanspruch nach Absatz 1 ist ausgeschlossen, sobald der jeweilige Betrag der Lastschriftbelastungsbuchung durch eine ausdrückliche Genehmigung des Kunden unmittelbar gegenüber der Bank autorisiert worden ist.</p>', '6413c305-85fa-482e-b5f9-3193056f77d9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1643402d-fc09-45c7-a9c8-e95303530ca5', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>2 The entitlement to a refund under paragraph 1 shall be precluded as soon as the amount of the direct debit entry has been expressly authorised by the customer directly to the Bank.</p>', '6413c305-85fa-482e-b5f9-3193056f77d9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5993bc0c-90bf-487d-b9a8-4a7c930cd9df', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>1 El derecho de reintegro según el inciso 1 quedará excluido cuando el cliente haya autorizado directamente al Banco de forma explícita a ejecutar el pago del importe de la contabilización del débito por nota de débito.</p>', '6413c305-85fa-482e-b5f9-3193056f77d9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('60a52213-0c9b-4614-beb9-8d3b459f7c4b', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>3 Erstattungsansprüche des Kunden bei einer nicht erfolgten oder fehlerhaft ausgeführten autorisierten Zahlung richten sich nach Nummer 2.6.2.</p>', '6e7580d7-2be1-4ba1-898b-b50aaba9c707');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4c5b1181-98aa-47fa-b262-bc487838ddf2', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>3 The customer&#39;s entitlement to a refund for a non-executed or incorrectly executed authorised payment shall be determined by Section 2.6.2.</p>', '6e7580d7-2be1-4ba1-898b-b50aaba9c707');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1c361092-0da1-43f2-a2c9-3336496ee2b6', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>Los derechos de reintegro del cliente en caso de pagos autorizados no ejecutados o ejecutados incorrectamente se rigen conforme a lo estipulado en el punto 2.6.2.</p>', '6e7580d7-2be1-4ba1-898b-b50aaba9c707');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2fb7479a-a334-448c-87c6-b2a51df8687d', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.6 Erstattungs-, Berichtigungs- und Schadensersatzansprüche des Kunden</h2>', '74be21be-34e9-462f-a783-d9336132ed49');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9419f478-1972-411a-bba9-5dd37cbf5c58', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.6 Customer&#39;s entitlement to a refund, correction and compensation</h2>', '74be21be-34e9-462f-a783-d9336132ed49');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dd1a09f4-9b38-4999-a373-0aefc78869d0', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.6 Derechos de reintegro, rectificación y por daños y perjuicios del cliente</h2>', '74be21be-34e9-462f-a783-d9336132ed49');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('6f1519b9-b2ae-40da-aa0e-a37128f1285e', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.6.1 Erstattung bei einer nicht autorisierten Zahlung</h2>', 'ab2dc192-5442-4aa1-b716-1896b81e055f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dd799fcd-dc17-4ca4-9751-e8eed94fc38b', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.6.1 Refund for an unauthorised payment</h2>', 'ab2dc192-5442-4aa1-b716-1896b81e055f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f9b869f0-6293-4ea7-b72c-4fbc4af52c68', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.6.1 Reintegro en caso de pagos no autorizados</h2>', 'ab2dc192-5442-4aa1-b716-1896b81e055f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c658f995-4d10-4de4-b331-37cb654a6517', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Im Falle einer vom Kunden nicht autorisierten Zahlung hat die Bank gegen den Kunden keinen Anspruch auf Erstattung ihrer Aufwendungen. Sie ist verpflichtet, dem Kunden den von seinem Konto abgebuchten Lastschriftbetrag zu erstatten. Dabei bringt sie das Konto wieder auf den Stand, auf dem es sich ohne die Belastung durch die nicht autorisierte Zahlung befunden hätte. Diese Verpflichtung ist spätestens bis zum Ende des Geschäftstags gemäß «Preis- und Leistungsverzeichnis» zu erfüllen, der auf den Tag folgt, an welchem der Bank angezeigt wurde, dass die Zahlung nicht autorisiert ist oder die Bank auf andere Weise davon Kenntnis erhalten hat. Hat die Bank einer zuständigen Behörde berechtigte Gründe für den Verdacht, dass ein betrügerisches Verhalten des Kunden vorliegt, schriftlich mitgeteilt, hat die Bank ihre Verpflichtung aus Satz 2 unverzüglich zu prüfen und zu erfüllen, wenn sich der Betrugsverdacht nicht bestätigt.</p>', '4dfb1ec7-e1c5-4530-b33d-4f977b395d94');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e3e82e9d-8487-4add-ab3a-0c8a75798f11', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>If a payment is not authorised by the customer, the Bank shall have no claim against the customer for reimbursement of its expenses. It shall be obligated to refund the amount debited to the customer&#39;s account to the customer and to restore the balance of this account to what it would have been without debiting for the unauthorised payment. This obligation is to be fulfilled by no later than the end of the business day according to the &quot;List of Prices and Services&quot;, which follows the day on which it was reported to the Bank that the payment is not authorised or the Bank has gained knowledge thereof in another manner. If the Bank has informed a responsible authority in writing of legitimate reasons for the suspicion that there is a fraudulent conduct of the customer, the Bank has to examine and fulfil its duties from Sentence 2 without delay if the suspicion of fraud is not confirmed.</p>', '4dfb1ec7-e1c5-4530-b33d-4f977b395d94');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cbf2cf23-922f-42f1-aa98-d2f27687567d', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>En caso de un pago no autorizado por el cliente, el Banco no tendrá derecho a solicitar del cliente el reintegro de sus gastos. El banco está obligado a reintegrar al cliente el importe de la nota de débito cargado a su cuenta. En dicho caso, el Banco deberá reponer la cuenta en el estado en el cual ésta se hubiera encontrado en caso de no haberse debitado el pago no autorizado. Esta obligación ha de ser cumplida a más tardar hasta el fin de la jornada laboral conforme a la &quot;Índice de precios y servicios&quot;, que sigue a la jornada en la que al banco se le indicó que el pago no estaba autorizado o en la que el banco tuvo conocimiento por otros medios. Si el banco le ha comunicado por escrito a la autoridad competente razones justificadas de la sospecha de que existe un comportamiento fraudulento del cliente, el banco tiene que comprobar y cumplir con su obligación de la proposición 2 si la sospecha de fraude no se confirma.</p>', '4dfb1ec7-e1c5-4530-b33d-4f977b395d94');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('117a9c4a-c1a1-4395-8c26-73b8c093b213', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.6.2 Ansprüche bei nicht erfolgter fehlerhafter oder verspäteter Ausführung von autorisierten Zahlungen</h2>', '75b8e41e-0492-4f6a-a116-130fbf0bc213');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b175f4e8-62a5-4b16-87fa-b4f8e5fc83dc', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.6.2 Claims for non-executed, incorrectly or late executed authorised payments</h2>', '75b8e41e-0492-4f6a-a116-130fbf0bc213');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c559012a-8ce5-43d6-b43b-a7486e53f78d', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.6.2 Derechos en caso de falta de ejecución, de ejecución incorrecta o tardía de pagos autorizados</h2>', '75b8e41e-0492-4f6a-a116-130fbf0bc213');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ddd0ff4f-5220-4fd5-b47b-9b02d7d4407b', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>1 Im Falle einer nicht erfolgten oder fehlerhaften Ausführung einer autorisierten Zahlung kann der Kunde von der Bank die unverzügliche und ungekürzte Erstattung des Lastschriftbetrages insoweit verlangen, als die Zahlung nicht erfolgt oder fehlerhaft war. Die Bank bringt dann das Konto wieder auf den Stand, auf dem es sich ohne den fehlerhaft ausgeführten Zahlungsvorgang befunden hätte.</p>', 'd6bb0e4e-d950-40c1-b995-654cf30d695f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('159d5066-3212-4c8f-9049-5579ee568a0f', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>1 If an authorised payment is not executed or not executed correctly, the customer may request the Bank to refund the direct debit amount in full without delay insofar as the payment was not executed or executed incorrectly. The Bank shall then restore the balance of the customer&#39;s account to what it would have been without debiting for the incorrectly executed payment transaction.</p>', 'd6bb0e4e-d950-40c1-b995-654cf30d695f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('58011662-7163-49d3-9709-137085a2e0fe', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>1 En caso de un pago autorizado no ejecutado o ejecutado incorrectamente, el cliente podrá exigir al Banco el reintegro inmediato y completo del importe de la nota de débito siempre que el pago no se haya ejecutado o se haya ejecutado incorrectamente. En dicho caso, el Banco deberá reponer la cuenta en el estado en que esta se hubiera encontrado si no se hubiese realizado la operación de pago incorrecta.</p>', 'd6bb0e4e-d950-40c1-b995-654cf30d695f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4a477ea8-b96a-453d-875d-e4b57b3fce29', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>2 Der Kunde kann über den Anspruch nach Absatz 1 hinaus von der Bank die Erstattung der Entgelte und Zinsen verlangen, soweit ihm diese im Zusammenhang mit der nicht erfolgten oder fehlerhaften Ausführung der Zahlung in Rechnung gestellt oder mit denen sie das Konto des Kunden belastet hat.</p>', '94d0a8ac-08e5-40eb-a597-4591766fe5f7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('066086bf-a1f0-45d4-ba47-e886cb3352d3', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>2 Over and above the entitlement under paragraph 1, the customer may request the Bank to refund the charges and interest levied on him/her or debited to his/her account in connection with the non-execution or incorrect execution of the payment.</p>', '94d0a8ac-08e5-40eb-a597-4591766fe5f7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('30a264f5-1567-40be-a2f4-c5fcce73b4ac', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>2 El cliente podrá exigir del Banco, aparte del derecho a tenor del apartado 1, el reintegro de todas las comisiones e intereses que el Banco le haya facturado o que haya debitado de su cuenta en relación con la ejecución del pago no realizada o realizada de forma incorrecta.</p>', '94d0a8ac-08e5-40eb-a597-4591766fe5f7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('39781beb-455d-4967-bb1a-45e9b026aaf8', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>3 Geht der Lastschriftbetrag beim Zahlungsdienstleister des Zahlungsempfängers erst nach Ablauf der Ausführungsfrist in Nummer 2.4.4 Absatz 2 ein (Verspätung), kann der Zahlungsempfänger von seinem Zahlungsdienstleister verlangen, dass dieser die Gutschrift des Lastschriftbetrags auf dem Konto des Zahlungsempfängers so vornimmt, als sei die Zahlung ordnungsgemäß ausgeführt worden.</p>', '62240d3a-8564-4e84-951f-69b99aa7c9a6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2784696e-e775-47ac-8a78-5ee0b85586b2', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>3 If the direct debit amount is only received by the payee&#39;s payment service provider after the expiry of the execution deadline in Section 2.4.4 Paragraph 2 (Delay) the payee can request from its payment service provider that it carries out the credit of the direct debit amount into the payee&#39;s account to the extent that the payment has been properly carried out.</p>', '62240d3a-8564-4e84-951f-69b99aa7c9a6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('52e7dd72-a55e-4708-9879-307552987e55', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>3 Si el importe de la nota de débito entra al proveedor de servicios de pago del receptor del pago solo después del trascurso del plazo de ejecución en el número 2.4.4, inciso 2 (retraso), entonces el receptor del pago puede exigir de su proveedor de servicios de pago, que este lleve a cabo la nota de abono del importe de la nota de débito en la cuenta del receptor del pago como si el pago hubiera sido ejecutado reglamentariamente.</p>', '62240d3a-8564-4e84-951f-69b99aa7c9a6');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e8cf46e9-26ad-47ec-a6df-df3e27e7504c', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>4 Wurde ein Zahlungsvorgang nicht oder fehlerhaft ausgeführt, wird die Bank auf Verlangen des Kunden den Zahlungsvorgang nachvollziehen und den Kunden über das Ergebnis unterrichten.</p>', 'd8dce092-eca2-4a82-9fdf-e9b30cce47cb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('be570f77-c381-41e9-ade1-48dc6cd3e117', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>4 If a payment transaction was not executed or not executed correctly, the Bank shall, at the customer&#39;s request, make immediate efforts to trace the payment transaction and notify the customer of the outcome.</p>', 'd8dce092-eca2-4a82-9fdf-e9b30cce47cb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9b2650bb-fb43-49fb-ad49-ff09ac48ab05', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>4 Cuando una operación de pago no se haya ejecutado o se haya ejecutado incorrectamente, el cliente podrá solicitar al Banco que realice un seguimiento de la operación de pago y le informe sobre el resultado del mismo.</p>', 'd8dce092-eca2-4a82-9fdf-e9b30cce47cb');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a462c532-e8c0-4018-8e4c-b16ae19daaf2', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.6.3 Schadensersatz wegen Pflichtverletzung</h2>', '5843f89c-cbfc-4846-b906-ca25bbc0b3e9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('e8cd95ae-835a-4f46-9ab3-a9e582247588', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.6.3 Compensation owing to a breach of duty</h2>', '5843f89c-cbfc-4846-b906-ca25bbc0b3e9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('82d5d488-603d-4a6d-b561-747c33df5065', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.6.3 Indemnización por lesión de deberes</h2>', '5843f89c-cbfc-4846-b906-ca25bbc0b3e9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('faff340d-1ff6-4525-8ce5-22b726842843', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>1 Bei nicht erfolgter oder, fehlerhafter oder verspäteter Ausführung einer autorisierten Zahlung oder bei einer nicht autorisierten Zahlung kann der Kunde von der Bank einen Schaden, der nicht bereits von Nummern 2.6.1 und 2.6.2 erfasst ist, ersetzt verlangen. Dies gilt nicht, wenn die Bank die Pflichtverletzung nicht zu vertreten hat. Die Bank hat hierbei ein Verschulden, das einer von ihr zwischengeschalteten Stelle zur Last fällt, wie eigenes Verschulden zu vertreten. Hat der Kunde durch ein schuldhaftes Verhalten zu der Entstehung eines Schadens beigetragen, bestimmt sich nach den Grundsätzen des Mitverschuldens, in welchem Umfang Bank und Kunde den Schaden zu tragen haben.</p>', 'bcffd89d-9a0c-4c0d-bbc4-25ff29fa47ff');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9b65ebc2-79a1-4101-a99b-3e6892b7919c', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>1 If an authorised payment is not executed, not executed correctly or late or if a payment is unauthorised, the customer may request the Bank to provide compensation for any loss or damage not already covered by Sections 2.6.1 and 2.6.2. This shall not apply if the Bank is not responsible for the neglect of duty. The Bank shall be liable in this connection for any fault on the part of an intermediary institution to the same extent as for any fault on its own part. If the customer has contributed to the occurrence of any loss or damage through culpable conduct, the principles of contributory negligence shall determine the extent to which the Bank and the customer must bear the loss or damage.</p>', 'bcffd89d-9a0c-4c0d-bbc4-25ff29fa47ff');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cda3c8d8-81cd-4a8a-8124-0cdbfa1d6306', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>1  En caso de un pago autorizado no ejecutado o ejecutado incorrectamente o de la ejecución de un pago no autorizado, el cliente podrá exigir al Banco la indemnización de un daño no incluido ya en los puntos 2.6.1 y 2.6.2. Lo anterior no se aplica si el Banco no fuera responsable de la violación de la obligación. En este caso, el Banco deberá asumir como propia la responsabilidad que recaiga sobre otra entidad a la que el Banco haya delegado alguna tarea. Si el cliente contribuye con su comportamiento doloso a que se origine un perjuicio, se determinará según los principios de la responsabilidad concurrente en qué proporción el Banco y el cliente deberán asumir el perjuicio.</p>', 'bcffd89d-9a0c-4c0d-bbc4-25ff29fa47ff');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4e6f86a0-32da-4ad8-8cc2-d34e9c308520', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>2 Die Haftung nach Absatz 1 ist auf 12.500,– Euro begrenzt. Diese betragsmäßige Haftungsgrenze gilt nicht</p>', '6b39e973-43bc-41d4-a1bb-7186cc94d3ab');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('879bf8da-af51-472f-9dae-231afefda619', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>2 Liability under paragraph 1 shall be limited to EUR 12,500. This limitation on liability shall not apply to</p>', '6b39e973-43bc-41d4-a1bb-7186cc94d3ab');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('77ce4f25-cb98-4e6a-a6b3-ad74dd38fa30', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>2 La responsabilidad según el inciso 1 estará limitada a 12.500,– euros. Este importe de límite de responsabilidad no es válido</p>', '6b39e973-43bc-41d4-a1bb-7186cc94d3ab');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b8ef99a6-9828-4853-8437-781e02a64bbf', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>für nicht autorisierte Zahlungen,</li><li>bei Vorsatz oder grober Fahrlässigkeit der Bank,</li><li>für Gefahren, die die Bank besonders übernommen hat, und</li><li>für den dem Kunden entstandenen Zinsschaden, wenn der Kunde Verbraucher ist.</li></ul>', 'c6685847-0929-47bf-b5a8-5f5ee2cca71f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('02f8c95e-2a3f-430e-955e-b70fb8a0ce49', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>unauthorised payments</li><li>cases of deliberate intent or gross negligence by the Bank</li><li>risks which the Bank has assumed on an exceptional basis and,</li><li>if the customer is a consumer, loss of interest incurred by the customer.</li></ul>', 'c6685847-0929-47bf-b5a8-5f5ee2cca71f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('680c65bd-7653-4c77-bfda-009b747fb4d0', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>para pagos no autorizados,</li><li>en caso de dolo o negligencia grave por parte del Banco,</li><li>para peligros que el Banco haya asumido de forma especial y</li><li>para perjuicios concernientes a intereses que hayan afectado al cliente, si el cliente sea un consumidor.</li></ul>', 'c6685847-0929-47bf-b5a8-5f5ee2cca71f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c22b0047-21dd-400d-b8f2-c25b49cd0ec2', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.6.4 Ansprüche von Kunden, die keine Verbraucher sind</h2>', '025f8ef4-7282-420f-9000-fbbb507828f4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0461e1ed-f88b-4eec-939e-ad4f00fcd977', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.6.4 Claims by customers who are not consumers</h2>', '025f8ef4-7282-420f-9000-fbbb507828f4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c778c3ff-eed2-423c-9f76-947d4ecd8896', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.6.4 Derechos de los clientes que no sean consumidores</h2>', '025f8ef4-7282-420f-9000-fbbb507828f4');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('76374627-f761-4259-8853-245f66b51694', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Abweichend von den Ansprüchen in Nummer 2.6.2 und 2.6.3 haben Kunden, die keine Verbraucher sind, bei einer nicht erfolgten, fehlerhaft oder verspätet ausgeführten autorisierten Zahlung oder bei einer nicht autorisierten Zahlung neben etwaigen Herausgabeansprüchen nach § 667 BGB und §§ 812 ff. BGB lediglich Schadensersatzansprüche nach Maßgabe folgender Regelungen:</p>', '568af79b-79c2-4bd3-8e12-eb7d7897d68c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a233be6e-bf5c-48e9-ae7b-e7b9f06f4a6e', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>By way of derogation from claims under Sections 2.6.2 and 2.6.3, customers who are not consumers with a non-executed, inaccurately executed or late authorised payment or with an unauthorised payment shall only have a claim for compensation – besides any claims for restitution under Sections 667 and 812 ff. of the German Civil Code – in accordance with the following rules:</p>', '568af79b-79c2-4bd3-8e12-eb7d7897d68c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('0ed327e0-7545-439b-93ed-fbeb992230cc', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>A diferencia de los derechos estipulados en los puntos 2.6.2 y de los derechos de indemnización del punto 2.6.3, los clientes que no son consumidores sólo tendrán, en el caso de un pago no ejecutado, ejecutados incorrectamente o con tardanza o en un pago no autorizado, aparte de eventuales derechos a restitución según los artículos 667 y 812 ff. del Código Civil Alemán, derechos a indemnización de conformidad con las siguientes regulaciones:</p>', '568af79b-79c2-4bd3-8e12-eb7d7897d68c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2031e20f-773b-4282-bc7f-f78ac16e5960', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>Die Bank haftet für eigenes Verschulden. Hat der Kunde durch ein schuldhaftes Verhalten zu der Entstehung eines Schadens beigetragen, bestimmt sich nach den Grundsätzen des Mitverschuldens, in welchem Umfang Bank und Kunde den Schaden zu tragen haben.</p>', '41306392-5f84-4d20-9fa4-a7b7f423cafa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('7678a3e5-df4b-46cb-9708-301f487fd30c', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>The Bank shall be liable for its own fault. This shall not apply if the Bank is not responsible for the neglect of duty. If the customer has contributed to the occurrence of any loss or damage through culpable conduct, the principles of contributory negligence shall determine the extent to which the Bank and the customer must bear the loss or damage.</p>', '41306392-5f84-4d20-9fa4-a7b7f423cafa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f490636a-7652-44b6-9c6a-c1978a0e75ad', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>El banco asume responsabilices por la culposidad propia. Si el cliente contribuye con su comportamiento doloso a que se origine un perjuicio, se determinará según los principios de la responsabilidad concurrente en qué proporción el Banco y el cliente deben asumir el perjuicio. El banco no asume responsabilidades por negligencias de los agentes intermedios por el banco. En estos casos la responsabilidad queda limitada a la cuidadosa selección e instrucción del primer agente intermedio.</p>', '41306392-5f84-4d20-9fa4-a7b7f423cafa');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dffdc594-2947-4160-8794-a834e2371178', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>Für das Verschulden der von der Bank zwischengeschalteten Stellen haftet die Bank nicht. In diesen Fällen beschränkt sich die Haftung der Bank auf die sorgfältige Auswahl und Unterweisung der ersten zwischengeschalteten Stelle.</li><li>Ein Schadensersatzspruch des Kunden ist der Höhe nach auf den Lastschriftbetrag zuzüglich der von der Bank in Rechnung gestellten Entgelte und Zinsen begrenzt. Soweit es sich hierbei um die Geltendmachung von Folgeschäden handelt, ist der Anspruch auf höchstens 12.500 Euro je Zahlung begrenzt. Diese Haftungsbeschränkungen gelten nicht für Vorsatz oder grobe Fahrlässigkeit der Bank und für Gefahren, die die Bank besonders übernommen hat sowie für nicht autorisierte Zahlungen.</li></ul>', '3b541a75-5bb0-4f39-bf6f-3ac64b0d3e22');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c6219200-91e6-4c68-990b-8e874174a0d7', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>The Bank will not be liable for the fault of the intermediary bodies involved by the Bank. In these cases the liability of the Bank is limited to the careful selection and instructions of the first intermediary body.</li><li>The amount of the customer&#39;s claim for compensation shall be limited to the amount of the direct debit, plus the charges and interest levied by the Bank. Where claims for consequential loss or damage are asserted, such claims shall be limited to a maximum of € 12,500 per payment. These limitations on liability shall not apply to deliberate intent or gross negligence by the Bank or to risks which the Bank has assumed on an exceptional basis as well as for unauthorised payments.</li></ul>', '3b541a75-5bb0-4f39-bf6f-3ac64b0d3e22');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f153b2ce-6eeb-4e6c-b502-42c0495939df', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>El Banco no asume responsabilidades por negligencias de los agentes intermedios por el banco. En estos casos la responsabilidad queda limitada a la cuidadosa selección e instrucción del primer agente intermedio.</li><li>El monto del derecho a indemnización del cliente se limitará al importe de la nota de débito más comisiones e intereses que haya facturado el Banco. Si se trata de la reclamación de daños consecuenciales, la responsabilidad se limita a un importe máximo de 12 500,- euros por pago. Estas limitaciones de la responsabilidad no se aplican a dolo o negligencia grave cometida por el Banco y a riesgos que el Banco haya aceptado especialmente así como para pagos no autorizados.</li></ul>', '3b541a75-5bb0-4f39-bf6f-3ac64b0d3e22');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('86251523-fe23-48b1-b7d4-fb85b93ac7c3', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<h2>2.6.5 Haftungs- und Einwendungsausschluss</h2>', 'ab267c47-a26f-4af5-96b4-43562452d7ee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c56ae7bc-2219-4568-9830-4db32cb68d8c', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<h2>2.6.5 Preclusion of liability and objection</h2>', 'ab267c47-a26f-4af5-96b4-43562452d7ee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('196a4b7c-7c0d-4628-9153-af6791efc152', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<h2>2.6.5 Exclusión de responsabilidad y de objeciones</h2>', 'ab267c47-a26f-4af5-96b4-43562452d7ee');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('59ef1264-bd1b-40ee-9c28-60410dc7d815', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>1 Eine Haftung der Bank nach Nummern 2.6.2. bis 2.6.4 ist in folgenden Fällen ausgeschlossen:</p>', 'aff2358c-0a69-477a-a425-57e93f117d87');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('96ef5d23-d693-4678-8b3e-08ecbc3af539', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>1 Any liability by the Bank under Sections 2.6.2 – 2.6.4 shall be precluded in the following cases:</p>', 'aff2358c-0a69-477a-a425-57e93f117d87');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9f47f9a6-747b-48e2-a158-dafb59a22a57', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>1 Está excluida la responsabilidad del Banco según los puntos 2.6.2. a 2.6.4 en los siguientes casos:</p>', 'aff2358c-0a69-477a-a425-57e93f117d87');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fbb51829-10ab-48a9-ae90-5f2903a59f19', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>Die Bank gegenüber dem Kunden nachweist, dass der Zahlungsbetrag rechtzeitig und ungekürzt beim Zahlungsdienstleister des Zahlungsempfängers eingegangen ist</li><li>Die Zahlung wurde in Übereinstimmung mit der vom Zahlungsempfänger angegebenen fehlerhaften Kundenkennung des Zahlungsempfängers ausgeführt. In diesem Fall kann der Kunde von der Bank jedoch verlangen, dass sie sich im Rahmen ihrer Möglichkeiten darum bemüht, den Zahlungsbetrag wiederzuerlangen. Ist die Wiedererlangung des Zahlungsbetrags nach Satz 2 dieses Unterpunktes nicht möglich, so ist die Bank verpflichtet, dem Kunden auf schriftlichen Antrag alle verfügbaren Informationen mitzuteilen, damit der Kunde einen Anspruch auf Erstattung des Zahlungsbetrags geltend machen kann. Für die Tätigkeiten nach den Sätzen 2 und 3 dieses Unterpunkts berechnet die Bank das im «Preis- und Leistungsverzeichnis» ausgewiesene Entgelt.</li></ul>', '3201ac86-eb36-4f3d-8f19-ed625c14f1af');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('86056d79-b872-488b-bc47-d888dabbad4b', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>The Bank proves to the customer that the full amount of the payment reached the payee&#39;s payment service provider in due time or</li><li>The payment was executed in conformity with the incorrect unique identifier of the payee provided by the payee. In this case, the customer may, however, request the Bank to make reasonable efforts to recover the amount of the payment. If the recovery of the payment amount according to Sentence 2 of this sub-point is not possible the Bank undertakes to inform the customer, following a written request, of all available information in order for the customer to be able to assert a claim for   refund of the payment amount. (For doing so according to Sentences 2 and 3 of this sub-point, the Bank shall levy the charge for recovery set out in the &quot;Schedule of prices and services&quot;.</li></ul>', '3201ac86-eb36-4f3d-8f19-ed625c14f1af');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2ca48419-68b8-47e0-b5e6-af7b5a8990f6', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>El Banco comprueba ante el cliente que el importe del pago fue recibido por el proveedor de servicios de pago del beneficiario del pago puntualmente y sin deducciones.</li><li>El pago ha sido ejecutado de conformidad con una identificación de cliente incorrecta del beneficiario del pago indicada por el beneficiario del pago. No obstante, el cliente podrá exigir al Banco en estos casos que intente recuperar el importe del pago en la medida de sus posibilidades. Si la recuperación según el inciso 2 de este subpuntos no es posible, entonces el banco está obligado a comunicarle al cliente, previa solicitud por escrito, todas las informaciones, con objeto de que el cliente pueda reclamar un derecho de abono del monto del pago. El Banco cobrará para las actividades conforme a los incisos 2 y 3 de este subpunto las comisiones estipuladas en el &quot;Índice de precios y servicios&quot;.</li></ul>', '3201ac86-eb36-4f3d-8f19-ed625c14f1af');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8c94722a-d19b-43a0-9e37-78913e39e480', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>2 Ansprüche des Kunden nach Nummern 2.6.1 bis 2.6.4 und Einwendungen des Kunden gegen die Bank aufgrund nicht oder fehlerhaft ausgeführter Zahlungen oder aufgrund nicht autorisierter Zahlungen sind ausgeschlossen, wenn der Kunde die Bank nicht spätestens 13 Monate nach dem Tag der Belastung mit einer nicht autorisierten oder fehlerhaft ausgeführten Zahlung hiervon unterrichtet hat. Der Lauf der Frist beginnt nur, wenn die Bank den Kunden über die Belastungsbuchung der Zahlung entsprechend dem für Kontoinformationen vereinbarten Weg spätestens innerhalb eines Monats nach der Belastungsbuchung unterrichtet hat; anderenfalls ist für den Fristbeginn der Tag der Unterrichtung maßgeblich. Schadensersatzansprüche nach Nummer 2.6.3 kann der Kunde auch nach Ablauf der Frist in Satz 1 geltend machen, wenn er ohne Verschulden an der Einhaltung dieser Frist verhindert war.</p>', '13d673f0-e214-48c7-95aa-e288d6a47c65');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9ea0100e-02e6-4c33-96df-eca03b595335', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>2 Any claims by the customer under Sections 2.6.1 – 2.6.4 and any objections by the customer against the Bank as a result of non-execution or incorrect execution of payments or as a result of unauthorised payments shall be precluded if the customer fails to inform the Bank thereof within a period of 13 months at the latest after being debited for an unauthorised or incorrectly executed payment. This period shall start to run only once the Bank has informed the customer about the debit entry for the payment through the agreed account information channel no later than one month after the debit entry was made; otherwise the date on which the customer is informed shall  determine when the period commences. The customer may assert claims for compensation under Section 2.6.3 also after expiry of the period referred to in sentence 1 if he/she was prevented, through no fault of his/her own, from adhering to this period.</p>', '13d673f0-e214-48c7-95aa-e288d6a47c65');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('f38b2753-aff3-43c9-9bc2-a2c9f4369b9f', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>2 Quedan excluidos los derechos del cliente con arreglo a los puntos 2.6.1 a 2.6.4 y las objeciones del cliente ante el Banco en virtud de pagos no ejecutados o ejecutados incorrectamente, o en virtud de pagos no autorizados, cuando el cliente no haya informado al respecto al Banco en el transcurso de los 13 meses posteriores al día del asiento de una operación de pago no autorizada o ejecutada incorrectamente. El plazo comienza a correr solo cuando el Banco haya informado al cliente de la operación de débito por la vía convenida para la información de la cuenta antes de que venza el plazo de un mes, contado a partir del asiento; en caso contrario, para el comienzo del plazo será determinante el día de la información. El cliente podrá reclamar derechos a indemnización según el punto 2.6.3 incluso después de transcurrido el plazo indicado en la oración 1, cuando le haya sido imposible cumplir dicho plazo por motivos ajenos a su voluntad.</p>', '13d673f0-e214-48c7-95aa-e288d6a47c65');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('536d6425-a379-48ed-8d33-92f1e54d0175', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<p>3 Ansprüche des Kunden sind ausgeschlossen, wenn die einen Anspruch begründenden Umstände</p>', 'b8ba36b6-e7b0-4569-877f-f92edd02bb86');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8ecc05c1-6d22-4cf7-93f5-e1bbad58caa6', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<p>3 Any claims by the customer shall be precluded if the circumstances substantiating a claim</p>', 'b8ba36b6-e7b0-4569-877f-f92edd02bb86');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cef5cf91-f024-4b1e-b7e1-6cabe6178d70', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<p>3 Los derechos del cliente están excluidos cuando las circunstancias que fundamentan dichos derechos</p>', 'b8ba36b6-e7b0-4569-877f-f92edd02bb86');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d034168d-35a3-46c2-8249-304c283392aa', '2026-09-14 13:00:30.500', 'de', 1, 'DRAFT', '<ul><li>auf einem ungewöhnlichen und unvorhersehbaren Ereignis beruhen, auf das die Bank keinen Einfluss hat und dessen Folgen trotz Anwendung der gebotenen Sorgfalt nicht hätten vermieden werden können, oder</li><li>von der Bank aufgrund einer gesetzlichen Verpflichtung herbeigeführt wurden.</li></ul>', 'e9bda168-7f62-4298-ab0d-a3b00b52e033');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2760f791-a12a-46dc-a7f3-a16016e7a879', '2026-09-14 13:00:30.500', 'en', 1, 'DRAFT', '<ul><li>are based upon an abnormal and unforeseeable event beyond the control of the Bank and whose consequences could not have been avoided even by exercising due diligence</li><li>or were brought about by the Bank as a result of a statutory obligation.</li></ul>', 'e9bda168-7f62-4298-ab0d-a3b00b52e033');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('3660b293-fd11-4aa0-92ac-b0a35ef2487d', '2026-09-14 13:00:30.500', 'es', 1, 'DRAFT', '<ul><li>se basan en sucesos excepcionales o impredecibles sobre los cuales el Banco no tiene ninguna influencia y cuyas consecuencias no hubieran podido evitarse a pesar de haber obrado con la diligencia debida, o</li><li>se producen debido al cumplimiento de una obligación legal por parte del Banco.</li></ul>', 'e9bda168-7f62-4298-ab0d-a3b00b52e033');
